fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // Ensure both arrays have the same length
    assert_eq!(
        arr1.len(),
        arr2.len(),
        "Input arrays must have the same length"
    );

    // Pre-allocate the result vector with the known capacity
    let mut result = Vec::with_capacity(arr1.len());

    // Compute element-wise division
    for (a, b) in arr1.iter().zip(arr2.iter()) {
        // We assume b != 0 as per problem statement
        result.push(a / b);
    }

    result
}

fn main() {
    let a = vec![10, 20, 30, 40];
    let b = vec![2, 5, 3, 8];
    let res = element_wise_divide(&a, &b);
    println!("{:?}", res); // [5, 4, 10, 5]
}